-- ─────────────────────────────────────────────────────────────────────────────
-- STARTER ROLES, BROUGHT UP TO CURRENT POLICY.
--
-- GENERATED by scripts/generate-starter-roles-migration.ts from
-- ALL_STARTER_ROLES in scripts/install-starter-roles.ts. Do not hand-edit:
-- regenerate it. The previous conversion migration hand-copied that set and
-- the two drifted apart — by the time anyone compared, six of eight roles
-- disagreed and Super was short twelve capabilities.
--
-- WHY A MIGRATION AND NOT THE SCRIPT. The script does the same work, but it
-- is a second command somebody has to remember during a cutover. As a
-- migration it runs unattended with the rest of the chain, fails the deploy
-- loudly if it cannot complete, and leaves a version record of what the
-- database was given.
--
-- The script remains the way to apply policy changes AFTER this. This is a
-- one-time catch-up for a database many revisions behind.
--
-- SAFE TO RE-RUN. Every statement is an upsert or a scoped replace. It
-- never deletes a role, never touches a user's grant, and never overwrites
-- a Setting that already exists — so a role an operator created themselves
-- is untouched, and so is a role of ours they renamed.
-- ─────────────────────────────────────────────────────────────────────────────

-- ── Trainee ──

UPDATE "CustomRole" SET key = 'seedlings.trainee'
 WHERE name = 'Trainee' AND key IS NULL;

INSERT INTO "CustomRole" (id, key, name, description, "isSystem", "isLadderRung", "isPerspective", "perspectiveOrder", "perspectiveIcon", "inheritsFromId", "createdAt")
VALUES (gen_random_uuid()::text, 'seedlings.trainee', 'Trainee', 'Can see the work and be added to a visit by someone else, but cannot pick it up or act on it. Grant Field Clearance when they are ready.', true, true, true, 1, 'graduation-cap', NULL, now())
ON CONFLICT (key) DO UPDATE
  SET "isSystem" = true,
      "isLadderRung" = true,
      "isPerspective" = true,
      "perspectiveOrder" = 1,
      "perspectiveIcon" = 'graduation-cap',
      "inheritsFromId" = NULL;

DELETE FROM "RoleEntitlement"
 WHERE "customRoleId" = (SELECT id FROM "CustomRole" WHERE key = 'seedlings.trainee')
   AND entitlement NOT IN ('clients.contribute', 'clients.view', 'crews.view', 'equipment.view', 'estimates.accept', 'estimates.create', 'marketing.view', 'materials.charge', 'people.view', 'pricing.view', 'routes.plan', 'schedule.contribute', 'schedule.view', 'supplies.view');

INSERT INTO "RoleEntitlement" (id, "customRoleId", entitlement)
SELECT gen_random_uuid()::text, (SELECT id FROM "CustomRole" WHERE key = 'seedlings.trainee'), e
  FROM unnest(ARRAY['clients.contribute', 'clients.view', 'crews.view', 'equipment.view', 'estimates.accept', 'estimates.create', 'marketing.view', 'materials.charge', 'people.view', 'pricing.view', 'routes.plan', 'schedule.contribute', 'schedule.view', 'supplies.view']) AS e
ON CONFLICT ("customRoleId", entitlement) DO NOTHING;

